class M:
 def __str__(self):
  print("format")
  raise LookupError("broken")
e=ValueError(M())
print("made")
try: str(e)
except LookupError: print("caught")

class M:
 def __repr__(self):
  print("bad")
  return "m"
e=RuntimeError(M(),M())
print(len(e.args))

m=[]
try: assert False,m
except AssertionError as e: print(e.args[0] is m)

class M:
 def __str__(self):
  print("bad")
  return "m"
m=M()
try: assert False,m
except AssertionError as e: print(e.args[0] is m)

class I:
 def __iter__(self):
  yield 7
  raise ValueError("broken")
e=Exception(9)
t=e.args
try: e.args=I()
except ValueError: print(e.args is t,e.args[0])

e=Exception(9)
try: e.args=7
except TypeError: print(e.args[0])

outer=ValueError("outer")
try:
 try: raise outer
 except ValueError: raise TypeError("inner")
except TypeError as e: print(e.__context__ is outer,e.__cause__ is None,e.__suppress_context__)

a=LookupError()
try:
 try: raise a
 except LookupError: raise ValueError() from None
except ValueError as e: print(e.__context__ is a,e.__cause__ is None,e.__suppress_context__)

def e():
 print("exception")
 return ValueError()
def c():
 print("cause")
 return None
try: raise e() from c()
except ValueError: print("caught")

def c():
 raise LookupError("cause failed")
raise ValueError("error") from c()

c=TypeError()
def f():
 try: raise ValueError("x") from c
 except ValueError: raise
try: f()
except ValueError as e: print(e.__cause__ is c,e.__suppress_context__)

try:
 try: raise ValueError() from None
 finally: print("finally")
except ValueError: print("caught")

a=ValueError()
b=TypeError()
try:
 try: raise a
 except ValueError:
  try: raise b
  except TypeError: raise a
except ValueError as e: print(e is a,a.__context__ is b,b.__context__ is None)

e=ValueError()
try: raise e from e
except ValueError as caught: print(caught.__cause__ is caught,caught.__context__ is None)

def fail():
 raise ValueError("x") from TypeError("y")
def middle():
 try: fail()
 except ValueError: raise
middle()
